import { describe, it, expect } from 'vitest';
import { importIptablesConfig } from './index.js';
import { compileNftables } from '../../compile/nft/index.js';

const SAMPLE_IPTABLES_SAVE = `
# Generated by iptables-save v1.8.9
*nat
:PREROUTING ACCEPT [0:0]
:INPUT ACCEPT [0:0]
:OUTPUT ACCEPT [0:0]
:POSTROUTING ACCEPT [0:0]
-A PREROUTING -i eth0 -p tcp -m tcp --dport 8080 -j DNAT --to-destination 192.168.1.50:80 --comment "Web Port Forward"
-A POSTROUTING -o eth0 -j MASQUERADE --comment "WAN Masquerade"
COMMIT
*filter
:INPUT DROP [0:0]
:FORWARD DROP [0:0]
:OUTPUT ACCEPT [0:0]
-A INPUT -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
-A INPUT -i lo -j ACCEPT
-A INPUT -i eth1 -p tcp -m tcp --dport 22 -j ACCEPT --comment "Allow Admin SSH"
-A INPUT -p icmp -j ACCEPT --comment "Allow Ping"
-A FORWARD -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
-A FORWARD -i eth1 -o eth0 -j ACCEPT --comment "Allow LAN outbound to WAN"
-A FORWARD -i eth0 -o eth1 -p tcp -d 192.168.1.50 --dport 80 -j ACCEPT --comment "Allow Forwarded Web"
COMMIT
`;

describe('Linux iptables / nftables Importer', () => {
  it('parses iptables-save dumps into Axonwall DesiredState and compiles to nftables', () => {
    const report = importIptablesConfig(SAMPLE_IPTABLES_SAVE);

    expect(report.success).toBe(true);
    expect(report.vendor).toBe('iptables');
    expect(report.interfacesCount).toBeGreaterThanOrEqual(2);
    expect(report.rulesCount).toBe(4);
    expect(report.natRulesCount).toBe(2);

    // NAT
    expect(report.state.nat[0].type).toBe('dnat');
    expect(report.state.nat[0].targetIp).toBe('192.168.1.50');
    expect(report.state.nat[0].targetPort).toBe('80');
    expect(report.state.nat[1].type).toBe('masquerade');

    // Rules
    expect(report.state.rules[0].action).toBe('pass');
    expect(report.state.rules[0].destinationPort).toBe('22');
    expect(report.state.rules[0].description).toBe('Allow Admin SSH');

    const { nftScript } = compileNftables(report.state);
    expect(nftScript).toContain('table inet axonwall');
    expect(nftScript).toContain('192.168.1.50');
  });
});
